CREATE OR REPLACE FUNCTION public.rpc_resolve_sanctions_screening(p_screening_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
